require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}oecrm_require_csrf();oecrm_require_permission($conn,'timesheets','review');$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$reason=trim($_POST['reason']??'');if(!in_array($decision,['approved','rejected'],true)){http_response_code(400);exit('Invalid decision.');}if($decision==='rejected'&&$reason===''){$_SESSION['timesheet_flash']='Rejection reason is required.';header('Location: timesheets.php');exit;}$companyId=oecrm_current_company_id($conn);$actor=(int)$_SESSION['adminId'];$old=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM timesheet_entries WHERE id='.$id.' AND company_id='.$companyId.' AND status="submitted"'));if(!$old){$_SESSION['timesheet_flash']='Timesheet entry is no longer pending.';header('Location: timesheets.php');exit;}$reasonValue=$decision==='rejected'?$reason:null;$s=mysqli_prepare($conn,'UPDATE timesheet_entries SET status=?,rejection_reason=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND company_id=?');mysqli_stmt_bind_param($s,'ssiii',$decision,$reasonValue,$actor,$id,$companyId);mysqli_stmt_execute($s);mysqli_stmt_close($s);oecrm_audit($conn,'timesheets',$decision,'timesheet',$id,'Timesheet '.$decision,$old,['status'=>$decision,'employee_id'=>$old['employee_id'],'reason'=>$reason]);$_SESSION['timesheet_flash']='Timesheet entry '.$decision.'.';header('Location: timesheets.php');exit;
